  static properties = { hass:{attribute:false}, response:{state:true}, graph:{state:true}, busy:{state:true}, failure:{state:true}, saved:{state:true}, activeSection:{state:true}, inventoryOpen:{state:true}, inventoryPage:{state:true}, query:{state:true}, dashboard:{state:true}, installed:{state:true}, expert:{state:true}, step:{state:true}, selected:{state:true}, history:{state:true}, domainFilter:{state:true}, reviewQuery:{state:true}, notice:{state:true}, conflict:{state:true}, welcomed:{state:true} };
